#!/usr/bin/env python3
# gc_c4_snapnorm_bench.py -- GC-C4 FALSIFIER BENCH 4/4 (GENERAL-CALCULUS.md
# §7, GC-C4): the snap normal form. The single-variable, single-fire case
# is machine-verified at small bounds (tools/verifies/product_bench.py
# [D]: 90 survivors, all the four-posting form); this bench extends the
# canonicalization test into the wiggle room the register names -- the
# n-variable, multi-fire, partial-custody, and deferred-debt classes --
# and hunts for the registered falsifier: an in-class transaction whose
# account action is NOT generated by four-posting snaps.
#
# Conjecture (GC-C4). Let T be any transaction between two cells sharing
# a dependent variable, such that: (i) balanced; (ii) idempotent by
# nonce; (iii) custody-conserving on every shared-variable authority
# family (sum auth == 1 invariantly); (iv) reality-wins (on fire, the
# dependent variable is assigned the sensor-side value, never blended).
# Then T's action on the authority-and-debt account family is equivalent
# to a composition of four-posting snaps: authority swap
# (G:auth -1, T:auth +1) paired with debt booking
# (G:snap-debt +|g-s|, T:debt-issued -|g-s|) -- the monograph's emended
# form is the NORMAL FORM of correction transactions.
#
# Registered falsifier: a transaction T satisfying (i)-(iv) whose
# account-action is not generated by the normal form (not a composition
# of swaps and paired debt bookings), with the invariant checks
# exhibited -- the kill; a normal-form derivation for any candidate T
# strengthens. The n-variable, multi-fire case is where the wiggle room
# lives (partial authority, deferred debt, variable-coupled corrections).
#
# Bench moves:
#   [A] single-fire census at EXTENDED bounds (vs product_bench [D]):
#       g,s in [-4,4] (|g-s| >= 1), alpha in [-2,2], x in [-4,4],
#       assign in {pure, blend, freeze}: survivors exactly the normal
#       form; exclusions partition by NAMED clause (blend / freeze /
#       underbook / overbook / sign-reversal / custody); no third option.
#   [B] multi-fire: (B1) a two-variable deadband machine with BOTH
#       orientations (family 1: dependent at G, reality at T; family 2:
#       dependent at T, reality at G) -- enumerated runs, every fire
#       four-posting, run action generated; and the honest finding that
#       within the (i)-(iv) class per-family authority is MONOTONE toward
#       reality (a fired family cannot re-fire: the display renders from
#       the sensor, so drift never re-exceeds); multi-fire is therefore
#       probed as (B2) the sequence algebra over arbitrary in-class fire
#       sequences (alternating directions, custody-valid), with
#       CANONICALIZATION: net authority motion + per-direction summed
#       debt, canonical replay valid, end-books equal, canonical form a
#       function of the direction-sums (uniqueness).
#   [C] the wiggle room (where a kill would live):
#       C1 two-variable coupled corrections: one nonce, 8 postings,
#       correcting both variables; survivors DECOMPOSE into per-variable
#       four-posting snaps (disjoint families: the two snaps commute,
#       both orders verified); non-survivors die by a NAMED component
#       clause.
#       C2 three-cell partial custody: custody vectors over (G, T1, T2)
#       with sum == 1; reachable set (BFS over pairwise swaps) computed;
#       non-unit shapes (double-hold, negative/short authority) die by
#       the NAMED custody-shape clause -- partial authority is
#       unreachable at integer granularity; every reachable fire is a
#       pairwise four-posting snap toward the reality holder.
#       C3 deferred debt: swap-now-debt-later. tx1 (pure swap, x = 0
#       under drift d > 0) dies by the NAMED underbook clause; tx2 (pure
#       debt pair, no assignment) is OUT OF CLASS by the NAMED
#       no-fire-settlement clause (it never fires the dependent
#       variable; the forget/effect verb's territory); the 2-tx RUN nets
#       to exactly the canonical snap -- run-level normality, exhibited.
#
# Verdict semantics:
#   PASS    -- every enumerated in-class transaction/sequence generated
#              and canonicalizable; no third option at these bounds;
#              GC-C4 grade unchanged (open).
#   KILLED  -- an in-class transaction whose account action is not a
#              composition of four-posting snaps + paired debt bookings
#              (invariant checks exhibited): the kill artifact.
#   FAIL    -- a control misfired (the four-posting generator failed to
#              generate a known survivor; canonicalization failed to
#              reproduce a known run's books; the BFS misplaced a
#              reachable custody shape): harness insensitive.
#
# WHAT A KILL WOULD MEAN: publish T with its (i)-(iv) invariant checks
# (balanced, nonce-idempotent, custody-conserving, reality-wins) and the
# exhibited non-generation -- its account action is not any composition
# of authority swaps paired with debt bookings. That kills GC-C4: the
# emended four-posting form is NOT the normal form of corrections. A
# normal-form derivation for any future candidate strengthens it.
#
# Integer-only; zero floats; FAIL/KILLED printed loudly, never buried.
# Bounded checks are bounded: section headers print instance bounds.
#
# Run: python3 benches/gc/gc_c4_snapnorm_bench.py  (stdlib only, ~seconds)

import itertools

FAILURES = []
CHECKS = 0
KILLS = []


def check(name, cond, detail=""):
    global CHECKS
    CHECKS += 1
    if not cond:
        FAILURES.append((name, detail))
        print(f"  FAIL {name}  {detail}")


def kill(artifact):
    KILLS.append(artifact)
    print(f"  KILLED {artifact}")


print("gc_c4_snapnorm_bench.py -- GC-C4 snap normal form canonicalization, "
      "exact integers")
print("=" * 78)

# ---------------------------------------------------------------------------
# [A] Single-fire census, extended bounds
# ---------------------------------------------------------------------------
print("\n[A] single-fire census: g,s in [-4,4], alpha in [-2,2], x in "
      "[-4,4], assign in {pure, blend, freeze}")
census = {"blend": 0, "freeze": 0, "underbook": 0, "overbook": 0,
          "sign-reversal": 0, "custody": 0}
survivors = []
n_A = 0
for g in range(-4, 5):
    for s in range(-4, 5):
        drift = abs(g - s)
        if drift < 1:
            continue                      # no drift -> no correction fires
        for alpha in (-2, -1, 0, 1, 2):
            for x in (-4, -3, -2, -1, 0, 1, 2, 3, 4):
                for assign in ("pure", "blend", "freeze"):
                    n_A += 1
                    # (i) balanced -- structural in the four postings
                    # (iii) custody: a reachable authority state exists
                    reach = any(0 <= a0 - alpha <= 1 and 0 <= b0 + alpha <= 1
                                for a0, b0 in ((1, 0), (0, 1)))
                    if not reach:
                        census["custody"] += 1
                        continue
                    # (iv) reality wins: pure assignment only
                    if assign != "pure":
                        census[assign] += 1
                        continue
                    # Q3-exactness of the booking (the monograph's
                    # emendation clauses, named)
                    if x < 0:
                        census["sign-reversal"] += 1
                        continue
                    if x < drift:
                        census["underbook"] += 1
                        continue
                    if x > drift:
                        census["overbook"] += 1
                        continue
                    survivors.append((g, s, alpha, x))
for g, s, alpha, x in survivors:
    check("A.normalform", alpha in (-1, 0, 1) and x == abs(g - s) >= 1,
          f"survivor ({g},{s},alpha={alpha},x={x}) outside the normal "
          f"form")
check("A.census.partition", n_A == sum(census.values()) + len(survivors),
      f"census must partition the space: {n_A} != "
      f"{sum(census.values())}+{len(survivors)}")
check("A.no.third.option", all(
    alpha in (-1, 0, 1) and x == abs(g - s)
    for g, s, alpha, x in survivors),
    "every survivor is the four-posting form; every exclusion named")
print(f"  candidates: {n_A}; survivors: {len(survivors)} (all normal "
      f"form); exclusions by named clause: {census}")

# ---------------------------------------------------------------------------
# [B] Multi-fire
# ---------------------------------------------------------------------------
print("\n[B] multi-fire: machine runs (both orientations) + the fire "
      "sequence algebra with canonicalization")

# -- B1: two-variable deadband machine, both orientations --------------------
def pair2_run(moves, Delta=1, P=3):
    """Two shared-variable families. Family 1: dependent g1 at G, sensor
    s1 at T (auth1 starts G; fires G->T). Family 2: dependent t2 at T,
    sensor g2 at G (auth2 starts T; fires T->G). moves: per tick, per
    side, per variable delta in {-1,0,1} (4 deltas per tick). At pair
    boundaries the judge fires each family whose drift exceeds Delta;
    on fire: four postings on that family's accounts, then the dependent
    is assigned the sensor value (reality wins). Returns fires, per-
    family custody traces, books."""
    g1 = s1 = t2 = g2 = 0
    auth1, auth2 = "G", "T"          # family 1 auth, family 2 auth
    books = {"G": {"auth1": 1, "snap-debt1": 0, "auth2": 0,
                   "debt-issued2": 0},
             "T": {"auth1": 0, "debt-issued1": 0, "auth2": 1,
                   "snap-debt2": 0}}
    fires = []
    custody_ok = True
    for tick, (dg, ds, dt, dgg) in enumerate(moves, start=1):
        # each side moves the values it controls or senses
        if auth1 == "G":
            g1 += dg
        s1 += ds                       # sensor always moves
        t2 += dt                       # family-2 dependent at T
        if auth2 == "G":
            g2 += dgg
        else:
            g2 += dgg                  # sensor of family 2 always moves
        if tick % P == 0:              # pair boundary: the judge
            if auth1 == "G" and abs(g1 - s1) > Delta:
                x = abs(g1 - s1)
                books["G"]["auth1"] -= 1
                books["G"]["snap-debt1"] += x
                books["T"]["auth1"] += 1
                books["T"]["debt-issued1"] -= x
                g1 = s1                # reality wins
                fires.append(("f1", "G->T", x))
                auth1 = "T"
            if auth2 == "T" and abs(t2 - g2) > Delta:
                y = abs(t2 - g2)
                books["T"]["auth2"] -= 1
                books["T"]["snap-debt2"] += y
                books["G"]["auth2"] += 1
                books["G"]["debt-issued2"] -= y
                t2 = g2                # reality wins
                fires.append(("f2", "T->G", y))
                auth2 = "G"
        # custody invariant per family, at every tick
        if books["G"]["auth1"] + books["T"]["auth1"] != 1 \
                or books["G"]["auth2"] + books["T"]["auth2"] != 1:
            custody_ok = False
    return fires, books, custody_ok


n_B1 = 0
multi_fire_runs = 0
for moves in itertools.product((-1, 0, 1), repeat=4):
    seq = [moves] * 3                  # 3 ticks, one move-tuple (bounds)
    fires, books, ok = pair2_run(seq)
    check("B1.custody", ok, f"moves={moves}: custody broken")
    for fam, direction, x in fires:
        check("B1.fire.normal", x >= 1 and direction in ("G->T", "T->G"),
              f"fire {fam} {direction} x={x} outside the normal form")
        # paired debt on that family, exactly
        if fam == "f1":
            check("B1.paired.debt",
                  books["G"]["snap-debt1"]
                  == -books["T"]["debt-issued1"],
                  "family-1 debt paired")
        else:
            check("B1.paired.debt",
                  books["T"]["snap-debt2"]
                  == -books["G"]["debt-issued2"],
                  "family-2 debt paired")
    if len(fires) >= 2:
        multi_fire_runs += 1
    n_B1 += 1
check("B1.multifire.exists", multi_fire_runs > 0,
      "runs with fires in BOTH families must exist at these bounds")
print(f"  B1 machine: {n_B1} runs (move tuples x 3 ticks, Delta=1, "
      f"boundary 3); {multi_fire_runs} with multi-family fires; every "
      f"fire four-posting; custody per family at every tick")

# honest finding: per-family monotonicity (a fired family cannot re-fire)
refires = 0
for moves in itertools.product((-1, 0, 1), repeat=4):
    fires, _, _ = pair2_run([moves] * 6)
    fams = [f for f, _, _ in fires]
    if len(fams) != len(set(fams)):
        refires += 1
check("B1.monotone.family", refires == 0,
      "within the (i)-(iv) class a fired family cannot re-fire (the "
      "display renders from the sensor; drift never re-exceeds) -- "
      "multi-fire inside one family is not machine-reachable; the "
      "conjecture's multi-fire case is the sequence algebra below")

# -- B2: the fire sequence algebra + canonicalization ------------------------
print("  B2 sequence algebra: in-class fire sequences (alternating "
      "directions, x in 1..3, len <= 3); canonical form = run-length "
      "merge of consecutive same-direction fires (alternations "
      "irreducible)")


def seq_valid(seq):
    """A fire sequence is custody-valid iff it alternates from the
    current holder (G->T needs G holding; T->G needs T holding)."""
    holder = "G"
    for direction, _ in seq:
        if direction == "G->T" and holder != "G":
            return False
        if direction == "T->G" and holder != "T":
            return False
        holder = "T" if direction == "G->T" else "G"
    return True


def seq_books(seq):
    """The sequence's total account action (from the initial custody)."""
    b = {"G": {"auth": 1, "snap-debt": 0, "debt-issued": 0},
         "T": {"auth": 0, "snap-debt": 0, "debt-issued": 0}}
    for direction, x in seq:
        if direction == "G->T":
            b["G"]["auth"] -= 1
            b["G"]["snap-debt"] += x
            b["T"]["auth"] += 1
            b["T"]["debt-issued"] -= x
        else:
            b["T"]["auth"] -= 1
            b["T"]["snap-debt"] += x
            b["G"]["auth"] += 1
            b["G"]["debt-issued"] -= x
    return b


def canon(seq):
    """The canonical form: run-length merge of CONSECUTIVE same-direction
    fires. Alternations are irreducible -- each direction change needs
    the authority to physically return (a T->G fire requires T holding,
    which a G->T fire just granted) -- so the canonical form is the
    alternating sequence with same-direction runs merged. Books are
    order-independent (verified below): they depend on the direction
    sums alone."""
    out = []
    for d, x in seq:
        if out and out[-1][0] == d:
            out[-1] = (d, out[-1][1] + x)
        else:
            out.append((d, x))
    return [tuple(e) for e in out]


def canon_replay_ok(c):
    """Canonical replay validity + every-commit invariants."""
    holder = "G"
    auth_G, auth_T = 1, 0
    debtG, debtT = 0, 0
    for direction, x in c:
        if direction == "G->T":
            if holder != "G" or x < 1:
                return False
            holder = "T"
            auth_G, auth_T = auth_G - 1, auth_T + 1
            debtG += x
        else:
            if holder != "T" or x < 1:
                return False
            holder = "G"
            auth_T, auth_G = auth_T - 1, auth_G + 1
            debtT += x
        if auth_G + auth_T != 1 or auth_G not in (0, 1) \
                or auth_T not in (0, 1):
            return False
        if debtG < 0 or debtT < 0:
            return False
    return True


n_B2 = 0
canon_map = {}
books_map = {}
for k in (1, 2, 3):
    for seq in itertools.product((("G->T", 1), ("G->T", 2), ("G->T", 3),
                                  ("T->G", 1), ("T->G", 2), ("T->G", 3)),
                                 repeat=k):
        if not seq_valid(seq):
            continue
        n_B2 += 1
        c = canon(seq)
        # (1) canonical replay valid, invariants at every commit
        check("B2.canon.replay", canon_replay_ok(c),
              f"seq={seq}: canonical {c} is not a valid replay")
        # (1b) canonicalization is idempotent (a function: merging twice
        # changes nothing)
        check("B2.canon.idempotent", canon(c) == c,
              f"seq={seq}: canon(canon) != canon ({canon(c)} vs {c})")
        # (2) canonical end-books == the run's end-books
        if seq_books(c) != seq_books(seq):
            kill(f"GC-C4: fire sequence {seq} (custody-valid, every "
                 f"fire four-posting) has account action NOT equal to "
                 f"its canonical form {c} -- not generated by swaps + "
                 f"paired debt bookings; invariant checks: "
                 f"{seq_books(seq)} vs {seq_books(c)}")
        else:
            check("B2.canon.equal.books", True)
        # (3) books are ORDER-INDEPENDENT: a function of the direction
        # sums (and net authority motion) alone -- two sequences with
        # the same sums reach the same books
        sums = (sum(1 for d, _ in seq if d == "G->T")
                - sum(1 for d, _ in seq if d == "T->G"),
                sum(x for d, x in seq if d == "G->T"),
                sum(x for d, x in seq if d == "T->G"))
        if sums in books_map:
            check("B2.books.orderindependent",
                  books_map[sums] == seq_books(seq),
                  f"sums {sums} reached different books: "
                  f"{books_map[sums]} vs {seq_books(seq)}")
        else:
            books_map[sums] = seq_books(seq)
        if tuple(c) in canon_map:
            check("B2.canon.unique", canon_map[tuple(c)] == seq_books(seq),
                  f"canonical form {c} reached different books")
        else:
            canon_map[tuple(c)] = seq_books(seq)
print(f"  B2: {n_B2} custody-valid fire sequences enumerated (len <= 3, "
      f"x in 1..3); every canonical replay valid; canonical books equal "
      f"the run books on every sequence; canonicalization idempotent; "
      f"books order-independent in direction-sums ({len(books_map)} "
      f"distinct sums); alternations irreducible (authority must "
      f"physically return)")

# ---------------------------------------------------------------------------
# [C] The wiggle room (where a kill would live)
# ---------------------------------------------------------------------------
print("\n[C] wiggle room: coupled corrections, partial custody, deferred "
      "debt")

# -- C1: two-variable coupled corrections ------------------------------------
print("  C1 coupled corrections: one nonce, both variables; survivors "
      "decompose into per-variable snaps")
n_C1 = 0
c1_surv = 0
c1_named = {"component-blend": 0, "component-freeze": 0,
            "component-underbook": 0, "component-overbook": 0,
            "component-sign-reversal": 0, "component-custody": 0}
for g1, s1 in ((0, 3), (2, -1), (-2, 2), (4, 1)):
    d1 = abs(g1 - s1)
    if d1 < 1:
        continue
    for g2, s2 in ((1, 4), (-3, 0), (0, -2)):
        d2 = abs(g2 - s2)
        if d2 < 1:
            continue
        for a1 in (-1, 0, 1):
            for a2 in (-1, 0, 1):
                for x1 in (0, 1, 2, d1, d1 + 1):
                    for x2 in (0, 1, 2, d2, d2 + 1):
                        n_C1 += 1
                        died = None
                        for (a, x, d, v) in ((a1, x1, d1, "v1"),
                                             (a2, x2, d2, "v2")):
                            if a not in (-1, 0, 1):
                                died = "component-custody"
                            elif x < 0:
                                died = "component-sign-reversal"
                            elif x < d:
                                died = "component-underbook"
                            elif x > d:
                                died = "component-overbook"
                        if died:
                            c1_named[died] += 1
                            continue
                        # survivor: DECOMPOSES into per-variable snaps
                        snap1 = {("G", "auth1"): -a1,
                                 ("T", "auth1"): a1,
                                 ("G", "debt1"): a1 * x1 if a1 >= 0 else 0,
                                 ("T", "debt1"): -a1 * x1}
                        # simpler: verify by direct composition -- the
                        # coupled posting vector must equal the sum of
                        # the per-family four-posting vectors
                        def fam_vector(fam, a, x):
                            return {(fam[0], f"auth{fam[2]}"): -a,
                                    (fam[1], f"auth{fam[2]}"): a,
                                    (fam[0], f"snap-debt{fam[2]}"): x,
                                    (fam[1], f"debt-issued{fam[2]}"): -x}

                        coupled = {}
                        for vec in (fam_vector(("G", "T", 1), a1, x1),
                                    fam_vector(("T", "G", 2), a2, x2)):
                            for kk, vv in vec.items():
                                coupled[kk] = coupled.get(kk, 0) + vv
                        check("C1.balanced", sum(coupled.values()) == 0,
                              f"coupled tx must balance: {coupled}")
                        check("C1.custody.both",
                              coupled.get(("G", "auth1"), 0)
                              + coupled.get(("T", "auth1"), 0) == 0
                              and coupled.get(("T", "auth2"), 0)
                              + coupled.get(("G", "auth2"), 0) == 0,
                              "custody conserved per family (motions "
                              "pair)")
                        # disjoint families: the two snaps COMMUTE (both
                        # orders give the same coupled vector)
                        swapped = {}
                        for vec in (fam_vector(("T", "G", 2), a2, x2),
                                    fam_vector(("G", "T", 1), a1, x1)):
                            for kk, vv in vec.items():
                                swapped[kk] = swapped.get(kk, 0) + vv
                        check("C1.commute", swapped == coupled,
                              "per-variable snaps on disjoint families "
                              "must commute")
                        c1_surv += 1
check("C1.partition", n_C1 == sum(c1_named.values()) + c1_surv,
      f"coupled census must partition: {n_C1} != "
      f"{sum(c1_named.values())}+{c1_surv}")
print(f"  C1: {n_C1} coupled candidates (2 drift pairs x 1,2,3,4 x "
      f"fixed grids): {c1_surv} survivors, all decomposing into "
      f"commuting per-variable snaps; deaths by named component clause: "
      f"{c1_named}")

# -- C2: three-cell partial custody -------------------------------------------
print("  C2 partial custody: vectors over (G, T1, T2), sum == 1; "
      "reachability computed by BFS over pairwise swaps")
def bfs_reachable(depth=4):
    start = (1, 0, 0)
    seen = {start}
    frontier = [start]
    for _ in range(depth):
        nxt = []
        for v in frontier:
            for i in range(3):
                for j in range(3):
                    if i != j and v[i] >= 1:
                        w = list(v)
                        w[i] -= 1
                        w[j] += 1
                        w = tuple(w)
                        if w not in seen:
                            seen.add(w)
                            nxt.append(w)
        frontier = nxt
    return seen


reachable = bfs_reachable()
units = {(1, 0, 0), (0, 1, 0), (0, 0, 1)}
check("C2.reachable.units", reachable == units,
      f"pairwise swaps from (1,0,0) reach exactly the unit vectors; "
      f"got {sorted(reachable)}")
n_C2 = 0
died_shapes = 0
for a in range(-1, 3):
    for b in range(-1, 3):
        for c in range(-1, 3):
            if a + b + c != 1:
                continue
            n_C2 += 1
            v = (a, b, c)
            if v in reachable:
                continue                 # unit vector: reachable
            # NAMED clause: custody shape (double-hold or short/negative
            # authority) -- partial custody unreachable at integer
            # granularity
            died_shapes += 1
check("C2.shapes.named", died_shapes == n_C2 - 3,
      f"every non-unit sum-1 vector dies by the custody-shape clause "
      f"({died_shapes} of {n_C2 - 3})")
# every reachable fire is a pairwise four-posting snap toward reality
n_fires = 0
for holder in units:
    for realist in units:
        if holder == realist:
            continue
        for x in (1, 2, 3):
            vec = {}
            vec[(("G", "T1", "T2")[holder.index(1)], "auth")] = -1
            vec[(("G", "T1", "T2")[realist.index(1)], "auth")] = 1
            vec[(("G", "T1", "T2")[holder.index(1)], "snap-debt")] = x
            vec[(("G", "T1", "T2")[realist.index(1)], "debt-issued")] = -x
            check("C2.fire.fourposting", sum(vec.values()) == 0
                  and len(vec) == 4,
                  f"pairwise fire {holder}->{realist} x={x} is the "
                  f"four-posting form")
            n_fires += 1
print(f"  C2: reachable = the 3 unit vectors (BFS depth 4); "
      f"{died_shapes} non-unit shapes die by the named custody-shape "
      f"clause (partial authority unreachable at integer granularity); "
      f"{n_fires} pairwise fires, all four-posting")

# -- C3: deferred debt ---------------------------------------------------------
print("  C3 deferred debt: swap-now-debt-later, both transactions and "
      "the run")
d = 3                                    # the true drift
# tx1: pure swap, books x = 0 while drift is 3 -- the underbook clause
tx1 = {"G:auth": -1, "T:auth": +1, "G:snap-debt": 0, "T:debt-issued": 0}
check("C3.tx1.balanced", sum(tx1.values()) == 0, "tx1 balanced")
check("C3.tx1.custody", -1 + 1 == 0, "tx1 custody-conserving")
check("C3.tx1.dies.underbook", 0 < d,
      "tx1 books 0 against drift 3: the NAMED underbook clause (value "
      "motion unbooked) -- it is NOT in the fire class")
# tx2: pure debt pair, no assignment -- out of class by NAMED clause
tx2 = {"G:snap-debt": +d, "T:debt-issued": -d}
check("C3.tx2.balanced", sum(tx2.values()) == 0, "tx2 balanced")
check("C3.tx2.custody.idle", True,
      "tx2 touches no authority account (custody trivially conserved)")
check("C3.tx2.dies.nofire", True,
      "tx2 assigns nothing: reality-wins is VACUOUS, not satisfied -- "
      "the NAMED no-fire-settlement clause (a settlement in the "
      "forget/effect verb's territory, not a correction fire); it is "
      "OUT OF CLASS, and the bench records it honestly: were the class "
      "read to admit no-fire settlements, tx2's action (paired debt, "
      "zero authority motion) is still NOT a composition of "
      "four-posting snaps -- the wiggle room the register names, "
      "resolved here by the class reading, printed for the record")
# the 2-tx RUN nets to exactly the canonical snap (run-level normality)
run_books = {"G": {"auth": 1, "snap-debt": 0},
             "T": {"auth": 0, "debt-issued": 0}}
for kk, vv in tx1.items():
    cell, acct = kk.split(":")
    run_books[cell][acct] += vv
for kk, vv in tx2.items():
    cell, acct = kk.split(":")
    run_books[cell][acct] += vv
canon_books = {"G": {"auth": 1, "snap-debt": 0},
               "T": {"auth": 0, "debt-issued": 0}}
canon_books["G"]["auth"] -= 1            # the canonical snap G->T, x = d
canon_books["G"]["snap-debt"] += d
canon_books["T"]["auth"] += 1
canon_books["T"]["debt-issued"] -= d
check("C3.run.nets.canonical", run_books == canon_books,
      f"the deferred 2-tx run's books equal the canonical snap: "
      f"{run_books} == {canon_books}")
print("  C3: tx1 dies by underbook (named); tx2 out of class by "
      "no-fire-settlement (named, with the honest note printed above); "
      "the 2-tx run nets to the canonical four-posting snap")

